input.command:
cat > /tmp/p.py <<'E'
import re
p='components/ui/tabs.py'
s=open(p).read()
a=s.index('        trigger_id = props.get')
b=s.index('        click_handlers = ')
new='''        user_on_click = props.pop("on_click", None)
        user_on_mount = props.pop("on_mount", None)

        # Scripts must not bake the id/value at build time: triggers rendered by
        # rx.foreach share one create() call. The click script locates the
        # clicked trigger via a transient marker set from the runtime event, and
        # reads the value from its rendered data-value attribute.
        js_on_click = """
        (function() {
            var trigger = document.querySelector('[data-tabs-clicked]');
            if (!trigger) return;
            trigger.removeAttribute('data-tabs-clicked');
            var root = trigger.closest('[data-slot="tabs"]');
            if (!root) return;

            var value = trigger.getAttribute('data-value');
            root.dataset.value = value;
            root.querySelectorAll('[data-slot="tabs-trigger"]').forEach(function(t) {
                if (t.closest('[data-slot="tabs"]') !== root) return;
                t.setAttribute('data-active', t.getAttribute('data-value') === value ? 'true' : 'false');
            });
        })()
        """

        js_on_mount = """
        (function() {
            document.querySelectorAll('[data-slot="tabs-trigger"]').forEach(function(t) {
                var root = t.closest('[data-slot="tabs"]');
                if (!root) return;
                t.setAttribute('data-active', t.getAttribute('data-value') === root.dataset.value ? 'true' : 'false');
            });
        })()
        """

        click_script = rx.Var(
            "(_e.currentTarget.setAttribute('data-tabs-clicked', '1'), "
            + json.dumps(js_on_click)
            + ")"
        )

'''
s=s[:a]+new+s[b:]
s=s.replace('rx.call_script(js_on_click)','rx.call_script(click_script)')
open(p,'w').write(s)
E
.venv/bin/python /tmp/p.py; head -15 components/ui/tabs.py | grep -n import; grep -n uuid components/ui/tabs.py

